import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as s,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Cursor ecosystem learning map","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/cursor/index.md","filePath":"products/ai-coding/cursor/index.md","lastUpdated":1787110548000}'),n={name:"products/ai-coding/cursor/index.md"};function o(d,t,i,l,c,h){return s(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="cursor-ecosystem-learning-map" tabindex="-1">Cursor ecosystem learning map <a class="header-anchor" href="#cursor-ecosystem-learning-map" aria-label="Permalink to &quot;Cursor ecosystem learning map&quot;">​</a></h1><blockquote><p><strong>Cursor is Anysphere&#39;s coding-agent family</strong>: a local editor, a terminal CLI, cloud sandbox agents, a git forge, security review, visual UI direction, and an SDK. The fastest first hour is still Tab + Agent in the editor. This page is a map. It does not walk you through clicks.</p></blockquote><h2 id="who-this-is-for" tabindex="-1">Who this is for <a class="header-anchor" href="#who-this-is-for" aria-label="Permalink to &quot;Who this is for&quot;">​</a></h2><ul><li>Front-end / full-stack engineers moving from autocomplete to “let the agent edit the repo”</li><li>People who already know VS Code and are installing Cursor for the first time</li><li>Tech leads choosing among <strong>editor / CLI / Cloud / Bugbot / Origin / Security / Design / SDK</strong></li></ul><p><strong>Not this page:</strong> enterprise contracts, per-token price grids, or Anysphere internals.</p><h2 id="product-landscape" tabindex="-1">Product landscape <a class="header-anchor" href="#product-landscape" aria-label="Permalink to &quot;Product landscape&quot;">​</a></h2><p>Official docs treat these as <strong>product surfaces</strong>, not another Rules recap.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cursor family</span></span>
<span class="line"><span>├── Cursor editor (VS Code fork) — the local default</span></span>
<span class="line"><span>│   ├── Tab          — multi-line complete, cross-file jumps, auto-import</span></span>
<span class="line"><span>│   ├── Inline Edit  — Cmd+K / Ctrl+K on the current selection</span></span>
<span class="line"><span>│   ├── Chat / Agent — Cmd+I / Ctrl+I; one agent, four constraints</span></span>
<span class="line"><span>│   │   ├── Agent    — edit files, run commands</span></span>
<span class="line"><span>│   │   ├── Ask      — read-only Q&amp;A</span></span>
<span class="line"><span>│   │   ├── Plan     — editable plan, then implement</span></span>
<span class="line"><span>│   │   └── Debug    — hypotheses → logs → you reproduce → evidence</span></span>
<span class="line"><span>│   └── Design Mode  — Agents Window browser: click / draw / voice (Cmd+Shift+D)</span></span>
<span class="line"><span>├── Cursor CLI (\`agent\`) — interactive terminal, or \`agent -p\` headless / CI</span></span>
<span class="line"><span>├── Cloud Agents (formerly Background Agents)</span></span>
<span class="line"><span>│   └── Isolated VMs: clone, branch, test, open PRs</span></span>
<span class="line"><span>│       Start from: editor Cloud dropdown, cursor.com/agents, mobile / PWA,</span></span>
<span class="line"><span>│       Slack / GitHub \`@cursor\`, or prefix a CLI message with \`&amp;\`</span></span>
<span class="line"><span>├── Bugbot — automated PR review (bugs / security / quality)</span></span>
<span class="line"><span>│   └── Autofix spawns a Cloud Agent. Official name is Autofix, not a product called “Fixer”</span></span>
<span class="line"><span>├── Origin — Cursor&#39;s git forge (early beta). Host / mirror / PR / browse</span></span>
<span class="line"><span>├── Security Agents — Security Reviewer (PR) + Vulnerability Scanner (cron)</span></span>
<span class="line"><span>├── PR Routing &amp; Approval — assign reviewers; approve low-risk PRs</span></span>
<span class="line"><span>└── Cursor SDK — \`@cursor/sdk\` / \`cursor-sdk\` / Bridge. Same agent, in your process</span></span></code></pre></div><p>Also on the official nav (one line here, official pages — no extra Tutorial):</p><table tabindex="0"><thead><tr><th>Surface</th><th>Pick it when</th><th>Official</th></tr></thead><tbody><tr><td><strong>Mobile / iOS / PWA</strong></td><td>Start or review Cloud Agents from a phone</td><td><a href="https://cursor.com/docs/cloud-agent/mobile" target="_blank" rel="noreferrer">Mobile</a></td></tr><tr><td><strong>JetBrains</strong></td><td>Stay in IntelliJ / PyCharm / WebStorm via ACP</td><td><a href="https://cursor.com/docs/integrations/jetbrains" target="_blank" rel="noreferrer">JetBrains</a></td></tr><tr><td><strong>Xcode</strong></td><td>Xcode 26.3+ built-in MCP</td><td><a href="https://cursor.com/docs/integrations/xcode" target="_blank" rel="noreferrer">Xcode</a></td></tr><tr><td><strong>Plugins</strong></td><td>Bundle rules / skills / MCP / hooks</td><td><a href="https://cursor.com/docs/plugins" target="_blank" rel="noreferrer">Plugins</a></td></tr><tr><td><strong>Automations</strong></td><td>Cloud Agents on a schedule or event. Hosts Bugbot, Security Agents, PR Routing</td><td><a href="https://cursor.com/docs/cloud-agent/automations" target="_blank" rel="noreferrer">Automations</a></td></tr></tbody></table><p>Closest cousins on this site: Cloud Agents ≈ Claude remote / Dispatch and Gemini Jules; Design Mode ≈ <a href="./../claude/claude-design.html">Claude Design</a> (in-app overlay vs standalone canvas); CLI ≈ Claude Code / Codex in a terminal; Origin ≈ “hosted code”, not Rules.</p><h3 id="quick-decision-which-should-i-use" tabindex="-1">Quick decision: which should I use? <a class="header-anchor" href="#quick-decision-which-should-i-use" aria-label="Permalink to &quot;Quick decision: which should I use?&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What do you want?</span></span>
<span class="line"><span>├── Finish the line / next edit / this selection</span></span>
<span class="line"><span>│   ├── Next edit → Tab (do not start an Agent turn)</span></span>
<span class="line"><span>│   └── This selection / function → Inline Edit (Cmd+K / Ctrl+K)</span></span>
<span class="line"><span>├── Ask, edit, plan, or debug in the local repo</span></span>
<span class="line"><span>│   └── Editor Agent (Cmd+I; Cmd+. for the mode menu)</span></span>
<span class="line"><span>│       ├── Understand first, do not touch files → Ask</span></span>
<span class="line"><span>│       ├── Clear multi-file work / tests → Agent</span></span>
<span class="line"><span>│       ├── Large or fuzzy change → Plan (Shift+Tab in the input)</span></span>
<span class="line"><span>│       ├── Reproducible bug, unknown cause → Debug</span></span>
<span class="line"><span>│       └── Point at the running UI → Design Mode (Cmd+Shift+D)</span></span>
<span class="line"><span>├── You are in a terminal, or a script / CI needs headless</span></span>
<span class="line"><span>│   └── Cursor CLI (\`agent\`)</span></span>
<span class="line"><span>│       ├── Interactive → \`agent\`</span></span>
<span class="line"><span>│       ├── Read-only → \`agent --mode=ask\`</span></span>
<span class="line"><span>│       ├── Plan first → \`agent --mode=plan\` / \`--plan\`</span></span>
<span class="line"><span>│       └── Script / CI → \`agent -p\`; add \`--force\` to apply edits</span></span>
<span class="line"><span>├── You are away, need parallelism, or want an isolated VM + PR</span></span>
<span class="line"><span>│   └── Cloud Agents</span></span>
<span class="line"><span>│       ├── Editor / web / iOS / Android PWA</span></span>
<span class="line"><span>│       ├── Slack, GitHub, Linear: \`@cursor\`</span></span>
<span class="line"><span>│       └── In a CLI session, prefix the message with \`&amp;\`</span></span>
<span class="line"><span>├── Host the code itself (not just review a GitHub PR)</span></span>
<span class="line"><span>│   └── Origin (Pro / Teams / Enterprise; claim a codebase name)</span></span>
<span class="line"><span>├── Security scan or PR security gate</span></span>
<span class="line"><span>│   └── Security Agents (\`/review-security\`; Automations)</span></span>
<span class="line"><span>├── Route reviewers / auto-approve low-risk PRs</span></span>
<span class="line"><span>│   └── PR Routing &amp; Approval (\`APPROVAL_POLICY.md\`)</span></span>
<span class="line"><span>├── Call the same agent from your TypeScript / Python / other runtime</span></span>
<span class="line"><span>│   └── Cursor SDK (\`@cursor/sdk\` / \`cursor-sdk\` / Bridge)</span></span>
<span class="line"><span>└── The PR is already pushed (or you want a diff review first)</span></span>
<span class="line"><span>    └── Bugbot</span></span>
<span class="line"><span>        ├── Hosted auto-review / comment \`cursor review\`</span></span>
<span class="line"><span>        ├── Local \`/review-bugbot\` before you push</span></span>
<span class="line"><span>        └── Machine should also patch → Autofix (Cloud Agent), not Debug Mode</span></span></code></pre></div><table tabindex="0"><thead><tr><th>You care about</th><th>Pick</th><th>Next</th></tr></thead><tbody><tr><td>IDE with Tab + Agent + rules</td><td><strong>Cursor editor</strong></td><td><a href="./cursor.html">Tutorial</a></td></tr><tr><td>Click / draw / voice on the running UI</td><td><strong>Design Mode</strong></td><td><a href="./design-mode.html">Design Mode</a></td></tr><tr><td>Terminal or headless CI, same Cursor rules / MCP</td><td><strong>Cursor CLI</strong></td><td><a href="./cursor-cli.html">CLI</a></td></tr><tr><td>Away / parallel / isolated VM + PR</td><td><strong>Cloud Agents</strong></td><td><a href="./cloud-agents.html">Cloud Agents</a></td></tr><tr><td>Machine reviews the PR first</td><td><strong>Bugbot</strong></td><td><a href="./cursor-cookbook.html#review-prs-with-bugbot">Cookbook · Bugbot</a></td></tr><tr><td>Host / mirror / browse the repo</td><td><strong>Origin</strong></td><td><a href="./origin.html">Origin</a></td></tr><tr><td>Security bugs on PRs or on a cron</td><td><strong>Security Agents</strong></td><td><a href="./security-agents.html">Security Agents</a></td></tr><tr><td>Assign reviewers / approve low-risk PRs</td><td><strong>PR Routing</strong></td><td><a href="./pr-routing.html">PR Routing</a></td></tr><tr><td>Same agent inside your process</td><td><strong>SDK</strong></td><td><a href="./cursor-sdk.html">Cursor SDK</a></td></tr><tr><td>Phone</td><td><strong>iOS app / Android PWA</strong></td><td><a href="https://cursor.com/docs/cloud-agent/mobile" target="_blank" rel="noreferrer">Mobile</a></td></tr><tr><td>JetBrains / Xcode</td><td><strong>ACP / Xcode MCP</strong></td><td><a href="https://cursor.com/docs/integrations/jetbrains" target="_blank" rel="noreferrer">JetBrains</a> · <a href="https://cursor.com/docs/integrations/xcode" target="_blank" rel="noreferrer">Xcode</a></td></tr><tr><td>Package skills + MCP</td><td><strong>Plugins</strong></td><td><a href="https://cursor.com/docs/plugins" target="_blank" rel="noreferrer">Plugins</a></td></tr><tr><td>Schedule or event-driven Cloud runs</td><td><strong>Automations</strong></td><td><a href="https://cursor.com/docs/cloud-agent/automations" target="_blank" rel="noreferrer">Automations</a></td></tr><tr><td>Terminal, fine-grained permissions, Anthropic stack</td><td><a href="./../claude/claude-code.html">Claude Code</a></td><td>Claude map</td></tr><tr><td>Stay inside stock VS Code + GitHub</td><td><a href="./../copilot.html">GitHub Copilot</a></td><td>Copilot page</td></tr></tbody></table><p>The full capability matrix, shortcuts, and config templates live on the <a href="./cursor-cheatsheet.html">cheatsheet</a>. This overview does not repeat that table.</p><h2 id="concepts-in-one-line" tabindex="-1">Concepts in one line <a class="header-anchor" href="#concepts-in-one-line" aria-label="Permalink to &quot;Concepts in one line&quot;">​</a></h2><p>Full “what / why” lives in the <a href="./cursor-glossary.html">glossary</a>.</p><table tabindex="0"><thead><tr><th>Concept</th><th>One line</th><th>Where</th></tr></thead><tbody><tr><td><strong>Tab</strong></td><td>Completion model; accept / reject trains the next suggestion</td><td>Editor</td></tr><tr><td><strong>Modes</strong></td><td>Agent / Ask / Plan / Debug — constraints, not four products</td><td>Editor / CLI</td></tr><tr><td><strong>Design Mode</strong></td><td>Visual prompts in the Agents Window browser</td><td>Editor</td></tr><tr><td><strong>Rules / AGENTS.md</strong></td><td>Persistent instructions in model context</td><td>Editor / CLI / Cloud</td></tr><tr><td><strong>Skills / Commands</strong></td><td>On-demand workflows; <code>/</code> to run</td><td>Editor / Cloud</td></tr><tr><td><strong>MCP / Hooks / Subagents</strong></td><td>External tools, lifecycle scripts, isolated children</td><td>Editor / CLI / Cloud (different limits)</td></tr><tr><td><strong>Cloud Agents</strong></td><td>Agents on isolated VMs; formerly Background Agents</td><td>Cloud</td></tr><tr><td><strong>Bugbot</strong></td><td>PR reviewer; Autofix then spawns a Cloud Agent</td><td>PR / <code>/review-bugbot</code></td></tr><tr><td><strong>CLI <code>agent</code></strong></td><td>Official terminal entry; <code>-p</code> for headless</td><td>Terminal / CI</td></tr><tr><td><strong>Origin</strong></td><td>Cursor git forge; binary <code>origin</code></td><td>Hosted code</td></tr><tr><td><strong>Security Agents</strong></td><td>PR reviewer + cron scanner on Automations</td><td>Cloud / <code>/review-security</code></td></tr><tr><td><strong>PR Routing</strong></td><td>Assign reviewers; maybe auto-approve</td><td>Automations</td></tr><tr><td><strong>SDK</strong></td><td>Same agent from <code>@cursor/sdk</code> / <code>cursor-sdk</code> / Bridge</td><td>Your process</td></tr></tbody></table><h2 id="feature-quick-reference" tabindex="-1">Feature quick reference <a class="header-anchor" href="#feature-quick-reference" aria-label="Permalink to &quot;Feature quick reference&quot;">​</a></h2><h3 id="editor" tabindex="-1">Editor <a class="header-anchor" href="#editor" aria-label="Permalink to &quot;Editor&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Purpose</th><th>Doc</th></tr></thead><tbody><tr><td>Tab</td><td>Cheap completions, no agent turn</td><td><a href="./cursor.html#tab-and-inline-edit">Tutorial · Tab</a></td></tr><tr><td>Inline Edit</td><td><code>Cmd+K</code> on a selection</td><td>same</td></tr><tr><td>Agent / Ask / Plan / Debug</td><td>Four constraints on one local agent</td><td><a href="./cursor.html#four-modes">Tutorial · Modes</a></td></tr><tr><td>Design Mode</td><td>Click / draw / voice in the Agents Window browser</td><td><a href="./design-mode.html">Design Mode</a></td></tr><tr><td>Rules / <code>AGENTS.md</code></td><td>Persist package manager and folder conventions</td><td><a href="./cursor.html#project-context">Tutorial · Project context</a></td></tr></tbody></table><h3 id="cli-cloud-review-host-sdk" tabindex="-1">CLI / Cloud / review / host / SDK <a class="header-anchor" href="#cli-cloud-review-host-sdk" aria-label="Permalink to &quot;CLI / Cloud / review / host / SDK&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Purpose</th><th>Doc</th></tr></thead><tbody><tr><td><code>agent</code></td><td>Same agent in a terminal</td><td><a href="./cursor-cli.html">CLI</a></td></tr><tr><td><code>agent -p</code> / <code>--force</code></td><td>Scripts and CI; <code>--force</code> to write files</td><td>same</td></tr><tr><td>Cloud Agents</td><td>Remote VM work and PRs</td><td><a href="./cloud-agents.html">Cloud Agents</a></td></tr><tr><td>Bugbot</td><td>Reviews a PR diff; default check is <code>neutral</code></td><td><a href="./cursor-cookbook.html#review-prs-with-bugbot">Cookbook · Bugbot</a></td></tr><tr><td>Autofix</td><td>Bugbot starts a Cloud Agent on findings</td><td>same</td></tr><tr><td>Origin</td><td>Host, mirror, browse, PR</td><td><a href="./origin.html">Origin</a></td></tr><tr><td>Security Agents</td><td>PR + cron security</td><td><a href="./security-agents.html">Security Agents</a></td></tr><tr><td>PR Routing</td><td>Route / approve</td><td><a href="./pr-routing.html">PR Routing</a></td></tr><tr><td>SDK</td><td>In-process agent</td><td><a href="./cursor-sdk.html">Cursor SDK</a></td></tr></tbody></table><h2 id="learning-path" tabindex="-1">Learning path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning path&quot;">​</a></h2><h3 id="stage-1-—-first-useful-change-in-five-minutes" tabindex="-1">Stage 1 — First useful change in five minutes <a class="header-anchor" href="#stage-1-—-first-useful-change-in-five-minutes" aria-label="Permalink to &quot;Stage 1 — First useful change in five minutes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Step</th><th>What</th><th>Link</th></tr></thead><tbody><tr><td>1</td><td>Install, sign in, open a folder</td><td><a href="./cursor.html#install-and-sign-in">Tutorial · Install</a></td></tr><tr><td>2</td><td><code>Cmd+I</code>: explain this repo</td><td><a href="./cursor.html#five-minute-first-example">Tutorial · First example</a></td></tr><tr><td>3</td><td>One low-risk edit, review the diff, run existing checks</td><td>same</td></tr><tr><td>4</td><td>Tell Tab / Inline Edit / Ask / Agent / Plan / Debug apart</td><td><a href="./cursor.html#four-modes">Tutorial · Modes</a></td></tr></tbody></table><h3 id="stage-2-—-teach-the-project" tabindex="-1">Stage 2 — Teach the project <a class="header-anchor" href="#stage-2-—-teach-the-project" aria-label="Permalink to &quot;Stage 2 — Teach the project&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Step</th><th>What</th><th>Link</th></tr></thead><tbody><tr><td>1</td><td>Root <code>AGENTS.md</code></td><td><a href="./cursor.html#project-context">Tutorial · Project context</a></td></tr><tr><td>2</td><td>Split <code>.cursor/rules/*.mdc</code> by glob</td><td><a href="./cursor-cookbook.html#write-rules-that-stick">Cookbook · Rules</a></td></tr><tr><td>3</td><td><code>.cursorignore</code> for secrets</td><td><a href="./cursor-cheatsheet.html#ignore-files">Cheatsheet · Ignore</a></td></tr></tbody></table><h3 id="stage-3-—-real-workflows" tabindex="-1">Stage 3 — Real workflows <a class="header-anchor" href="#stage-3-—-real-workflows" aria-label="Permalink to &quot;Stage 3 — Real workflows&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Step</th><th>What</th><th>Link</th></tr></thead><tbody><tr><td>1</td><td>Bugs / Debug Mode</td><td><a href="./cursor-cookbook.html#fix-bugs">Cookbook · Bugs</a></td></tr><tr><td>2</td><td>Plan → implement → verify</td><td><a href="./cursor-cookbook.html#ship-a-multi-file-feature">Cookbook · Features</a></td></tr><tr><td>3</td><td>Bugbot on PRs</td><td><a href="./cursor-cookbook.html#review-prs-with-bugbot">Cookbook · Bugbot</a></td></tr><tr><td>4</td><td>MCP / Hooks / parallel agents</td><td><a href="./cursor-cookbook.html">Cookbook</a></td></tr><tr><td>5</td><td>Visual UI edits</td><td><a href="./design-mode.html">Design Mode</a></td></tr><tr><td>6</td><td>Lookup</td><td><a href="./cursor-cheatsheet.html">Cheatsheet</a></td></tr><tr><td>7</td><td>Definitions</td><td><a href="./cursor-glossary.html">Glossary</a></td></tr></tbody></table><h3 id="stage-4-—-leave-the-local-window" tabindex="-1">Stage 4 — Leave the local window <a class="header-anchor" href="#stage-4-—-leave-the-local-window" aria-label="Permalink to &quot;Stage 4 — Leave the local window&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Step</th><th>What</th><th>Link</th></tr></thead><tbody><tr><td>1</td><td>Install <code>agent</code>, run one interactive turn</td><td><a href="./cursor-cli.html">CLI</a></td></tr><tr><td>2</td><td>Dispatch one Cloud task</td><td><a href="./cloud-agents.html">Cloud Agents</a></td></tr><tr><td>3</td><td>Cloud ≠ Bugbot ≠ Debug</td><td><a href="./cursor-glossary.html#cloud-agents">Glossary · Cloud</a> · <a href="./cursor-glossary.html#bugbot">Bugbot</a></td></tr><tr><td>4</td><td>Host code on Origin, or scan / route PRs</td><td><a href="./origin.html">Origin</a> · <a href="./security-agents.html">Security Agents</a> · <a href="./pr-routing.html">PR Routing</a></td></tr><tr><td>5</td><td>Embed the agent</td><td><a href="./cursor-sdk.html">SDK</a></td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./cursor.html">Cursor tutorial</a></li><li><a href="./cursor-cookbook.html">Cookbook</a></li><li><a href="./design-mode.html">Design Mode</a></li><li><a href="./cloud-agents.html">Cloud Agents</a></li><li><a href="./cursor-cli.html">Cursor CLI</a></li><li><a href="./origin.html">Origin</a></li><li><a href="./security-agents.html">Security Agents</a></li><li><a href="./pr-routing.html">PR Routing</a></li><li><a href="./cursor-sdk.html">Cursor SDK</a></li><li><a href="./cursor-cheatsheet.html">Cheatsheet</a></li><li><a href="./cursor-glossary.html">Glossary</a></li><li><a href="./../">AI coding tools overview</a></li></ul>`,34)])])}const b=e(n,[["render",o]]);export{f as __pageData,b as default};
